{
  "headline": "Omeprazole is not on FDA's shortage list as of 2026-10-21; supply traces to two registered plants with VAI inspections",
  "headline_cites": ["D3", "E6", "E18"],
  "sentences": [
    {
      "text": "FDA's records show omeprazole is not on the drug shortage list as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale General holds 494 capsules of the 20 mg presentation at 19.1 per day, giving 25.9 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "Corvale East holds 36 capsules at 8.6 per day, giving 4.2 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "The rule‑ranked option is to transfer 85 capsules of 20 mg from Corvale General to Corvale East, which would leave the sender with two weeks' supply and bring the receiver to 14 days.",
      "cites": ["D4"]
    },
    {
      "text": "One source at Corvale General is labeled by Proficient Rx LP (FEI 3011557028), a registered plant whose most recent FDA inspection was classified VAI on 2022-12-08.",
      "cites": ["E2", "E6", "E5"]
    },
    {
      "text": "The other source is labeled by Bryant Ranch Prepack (FEI 1000519407), a registered plant whose most recent FDA inspection was classified VAI on 2026-07-16.",
      "cites": ["E3", "E18", "E16"]
    },
    {
      "text": "Alternate manufacturers Advanced Rx Pharmacy of Tennessee, LLC and Advanced Rx of Tennessee, LLC are not on the FDA shortage list today, but their labels name no plant we could place.",
      "cites": ["D5", "D6"]
    }
  ]
}
